#!/usr/bin/env python3
"""Canonical VPERMD against independent Python tuple selection."""
import hashlib,itertools,json,pathlib,random,subprocess
R=pathlib.Path(__file__).resolve().parents[1];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();out=R/'generated/sse/vpermd-reference';out.mkdir(parents=True,exist_ok=True);rng=random.Random(25034);requests=[];expected=[]
patterns=list(itertools.permutations(range(8)))+[(i,)*8 for i in range(8)]+[tuple(rng.randrange(8) for _ in range(8)) for i in range(4096)]
for mode in range(2):
 for i,pattern in enumerate(patterns):
  indices=[(rng.getrandbits(32)&0xfffffff8)|p for p in pattern];source=[(j+1)*0x1020304 if i<40328 else rng.getrandbits(32) for j in range(8)];data=[bytes(rng.getrandbits(8) for _ in range(32)),b''.join(v.to_bytes(4,'little') for v in indices),b''.join(v.to_bytes(4,'little') for v in source)];vectors=[[int.from_bytes(row[j:j+8],'little') for j in range(0,32,8)] for row in data]
  setting=i%16;sticky=[0,1,31,63][(i//16)%4];control=0x1f80|((setting&3)<<13)|(0x40 if setting&4 else 0)|(0x8000 if setting&8 else 0)|sticky;flags=[0,0x8d5,0x41,0x884][i%4];word=rng.getrandbits(32)
  requests.append(f'{mode} {control:x} {flags:x} {word:x} '+' '.join(f'{v:016x}' for row in vectors for v in row)+' 0\n');value=b''.join(source[k].to_bytes(4,'little') for k in pattern);expected.append([int.from_bytes(value[j:j+8],'little') for j in range(0,32,8)]+[v for row in vectors[1:] for v in row]+[word,control,flags]+vectors[2])
request=''.join(requests);(out/'requests.txt').write_text(request);source=R/'tests/vpermd_oracle.c';exe=out/'oracle-x86';subprocess.run(['clang','-arch','x86_64','-O2','-mno-red-zone','-Wall','-Wextra','-Werror',str(source),'-o',str(exe)],check=True);run=subprocess.run(['arch','-x86_64',str(exe)],input=request,text=True,capture_output=True,check=True,timeout=120);(out/'reference.txt').write_text(run.stdout);replies=run.stdout.splitlines();assert len(replies)==len(expected)
for i,(reply,want) in enumerate(zip(replies,expected)):assert [int(x,16) for x in reply.split()]==want,(i,reply,want)
r={'pass':True,'state':'finished','cases':len(expected),'modes':2,'source_sha256':sha(source),'verifier_sha256':sha(pathlib.Path(__file__)),'requests_sha256':sha(out/'requests.txt'),'reference_sha256':sha(out/'reference.txt'),'binary_sha256':sha(exe),'scope':'Canonical Rosetta VPERMD REG/MEM, all40320 permutations per mode, all repeated indices, mixed random selections and arbitrary high bits, full3YMM/flags/maskedMXCSR/memory. Separate native corpus, not physicalIntel/fullDLL initialization/gameplay proof.'};(out/'result.json').write_text(json.dumps(r,indent=2)+'\n');print('PASS: %d canonical VPERMD reference cases'%len(expected))
